  SELECT * FROM jsonb_populate_recordset(NULL::public.scoring_rules, $festos_scoring_rules_json$[{"id":"02068a9a-d4e1-4046-b01c-2e751c4a1172","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Nasheed","guidelines":null,"is_default":true,"time_limit":"7m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"നഷീദ്"},{"id":"0658ee80-8f29-47a4-8cf9-72c4ac1c6195","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Mappilappattu","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"മാപ്പിളപ്പാട്ട്"},{"id":"0682beac-5243-449b-bf8f-b8bc5c5e5aba","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Social Story","guidelines":"1. നിർദ്ദേശിക്കപ്പെടുന്ന വിഷയത്തെ കുറിച്ച് സോഷ്യൽ മീഡിയയിൽ പോസ്റ്റ് ചെയ്യാൻ പറ്റുന്ന രൂപത്തിലുള്ള പരമാവധി ഏഴ് മിനിട്ട് ദൈർഘ്യമുള്ള വീഡിയോ അവതരണമാണ് സോഷ്യൽ സ്‌റ്റോറി.\n2. നേരത്തെ നൽകപ്പെടുന്ന വിഷയത്തിൽ മത്സരാർഥി സ്വയം അവതരിപ്പിക്കുന്ന രൂപത്തിലാണ് വീഡിയോ തയ്യാറാക്കേണ്ടത്.\n3. തയ്യാറാക്കുന്ന വീഡിയോ വിഷയത്തിൽ ആധികാരികമായ അവലംബങ്ങൾ ആശ്രയിച്ചുള്ള നല്ല പഠനം ആവാൻ ശ്രദ്ധിക്കുക. അവലംബങ്ങളിൽ നിന്ന് ഉദ്ധരണികൾ ഉപയോഗിക്കാം.\n4. അനാവശ്യ വിമർശനങ്ങൾ ഇല്ലാതെ സുതാര്യമായ സമീപനം സ്വീകരിക്കുകയാണ് അഭികാമ്യം.\n5. നിശ്ചയിക്കപ്പെടുന്ന സമയത്തിന് മുമ്പായി വീഡിയോ യൂട്യൂബിൽ പ്രൈവേറ്റായി അപ്‌ലോഡ് ചെയ്യുകയും ലിങ്ക് മെയിൽ ചെയ്യുകയും വേണം.\n6. ഉള്ളടക്കം, അവലംബങ്ങളിലെ കൃത്യത, അവതരണത്തിലെ മികവ്, ബാക്ക് ഗ്രൗണ്ട് പ്രസന്റേഷൻ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സോഷ്യൽ സ്‌റ്റോറി"},{"id":"06956e73-61db-45d6-af0d-f69a365f7d85","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Arabic Poetry Recitation","guidelines":"1. അറബി ഭാഷയിലുള്ള അധാർമിക സന്ദേശങ്ങൾ വരുന്നതല്ലാത്ത കവിതകളാണ് അവതരിപ്പിക്കേണ്ടത്.\n2. മനഃപാഠം, അക്ഷരസ്ഫുടത, മിതമായ ഭാവ-ശബ്ദ പ്രകടനം, അർഥം-ആശയം എന്നിവയുടെ സ്പഷ്ടത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കവിതാ പാരായണം/അറബിക് പദ്യം ചൊല്ലൽ"},{"id":"0af862de-82c2-4225-981b-4fef1344d24c","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Book Test","guidelines":"1. നിർദ്ദേശിക്കുന്ന ഐ.പി.ബി പുസ്തകം മത്സരാർഥി നേരത്തെ വായിച്ചിരിക്കണം.\n2. പ്രിന്റ് ചെയ്ത ചോദ്യാവലിയിൽ 5 ഡിസ്‌ക്രിപ്റ്റീവ് ചോദ്യങ്ങളും 10 ഒബ്ജക്ടീവ് ചോദ്യങ്ങളും ഉൾപ്പെടെ ആകെ 15 ചോദ്യങ്ങളാണ് വേണ്ടത്.\n3. ഇതിൽ 5 എണ്ണം സ്റ്റാർ മാർക്ക് ചെയ്ത് നൽകുക. ഈ അഞ്ചിൽ മൂന്നെണ്ണം ഒബ്ജക്ടീവും രണ്ടെണ്ണം ഡിസ്ക്രിപ്റ്റീവും ആയിരിക്കണം.\n4. ഒരു ഒബ്ജക്ടീവ് ചോദ്യത്തിന് ഒരു മാർക്കും ഒരു ഡിസ്ക്രിപ്റ്റീവ് ചോദ്യത്തിന് രണ്ട് മാർക്കും ആയിരിക്കും.\n5. സ്റ്റാർ മാർക്ക് ചെയ്ത ചോദ്യങ്ങൾക്ക് ലഭിച്ച ആകെ മാർക്ക് ടൈബ്രേക്കറായി പരിഗണിക്കും.\n6. സമയം 15 മിനിട്ട്.","is_default":true,"time_limit":"15m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ബുക്ക് ടെസ്റ്റ്"},{"id":"0db00b2c-fb42-4159-b757-e28ca2ea28ae","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Spot Magazine","guidelines":"1. മത്സരത്തിനാവശ്യമായ പേപ്പറുകൾ സംഘാടക സമിതി സീൽ ചെയ്ത് നൽകണം.\n2. മത്സര ഹാളിൽ വെച്ചാണ് വിഷയം നൽകുക.\n3. ആവശ്യമായ സാമഗ്രികൾ മത്സരാർഥികൾ കൊണ്ട് വരേണ്ടതാണ്.\n4. കവർ, ഉള്ളടക്കം മലയാള ഭാഷയിൽ മാത്രമാകണം.\n5. ആശയം, സാഹിത്യം, സംവിധാനം, സർഗ്ഗാത്മകത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സ്‌പോട്ട് മാഗസിൻ"},{"id":"1187ab00-0e3f-4392-81a8-be9417ce738f","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Collage","guidelines":"1. ഡിവിഷൻ, ജില്ലാ, സംസ്ഥാന സാഹിത്യോത്സവുകളിൽ മാത്രമേ ഈ മത്സരമുണ്ടാകുകയുള്ളൂ.\n2. മൂന്ന് ദിവസം മുമ്പ് കമ്മിറ്റി നൽകുന്ന വിഷയത്തെ അടിസ്ഥാനമാക്കി A3 സൈസിൽ സ്ലൈഡുകൾ തൽസമയം ഡിസൈൻ ചെയ്യണം.\n3. വര, പെയ്ന്റിംഗ്, എഴുത്ത്, ഫോട്ടോ, പത്രകട്ടിംഗ് എന്നിവ അനുവദനീയമാണ്.\n4. മത്സരത്തിനാവശ്യമായ പേപ്പർ സംഘാടകർ നൽകുന്നതാണ്. മറ്റ് സാമഗ്രികൾ മത്സരാർഥികൾ കരുതണം.\n5. 3 പേരാണ് മത്സരത്തിൽ പങ്കെടുക്കേണ്ടത്.\n6. വിഷയവുമായുള്ള ബന്ധം, കോംബിനേഷൻ, പ്രയോഗ രീതി, വിവിധ മാധ്യമങ്ങളുടെ സംകലനം, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കൊളാഷ്"},{"id":"17d13616-8e51-4601-9ccf-aab2e72b525b","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"E-Poster","guidelines":"1. നൽകുന്ന പോസ്റ്റർ മാറ്റർ മൊബൈൽ ഫോണിൽ നിശ്ചിത സമയത്തിനുള്ളിൽ ഡിസൈൻ ചെയ്യണം.\n2. മൊബൈൽ ഫോണിലെ ഏത് ആപ്പുകളും സോഫ്‌ട്‌വെയറുകളും ഇതിന് ഉപയോഗിക്കാം.\n3. സൃഷ്ടി മൗലികമായിരിക്കണം. ഉപയോഗിച്ച ഇമേജുകൾ കൂടെ അയക്കണം.\n4. വിഷയവുമായുള്ള പോസ്റ്ററിന്റെ പൊരുത്തവും ആശയാവതരണ പുതുമയും, രൂപങ്ങൾക്ക് തനിച്ചും പരസ്പരവും ഉണ്ടായിരിക്കേണ്ട അനുപാത പൊരുത്തം, ചിത്രം-ടെക്‌സ്റ്റ് എന്നിവക്ക് നിറങ്ങളുടെ പ്രയോഗം, ഡിജിറ്റൽ സാങ്കേതികതയുടെ വിദഗ്ധമായ പ്രയോഗവും ചിത്രത്തിന്റെ ആസ്വാദന ക്ഷമതയും വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഇ-പോസ്റ്റർ"},{"id":"1cee78ba-07dc-4f3d-ac41-8dc26bea290d","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Revolutionary Song Writing","guidelines":"1. ഇസ്‌ലാമിക വിപ്ലവ ചരിത്രം, സംഘടനാ മുന്നേറ്റം തുടങ്ങിയവ ഇതിവൃത്തമാകുന്ന പുതിയ ഗാനങ്ങൾ രചിക്കുകയാണ് വേണ്ടത്.\n2. നൽകപ്പെടുന്ന വിഷയത്തിൽ സംഘടനയുടെ ആശയം ജനങ്ങളിലെത്തിക്കാനും വിദ്യാർഥികളെ സംഘടനയുടെ വിപ്ലവ വഴിയിലേക്ക് ക്ഷണിക്കാനും കഴിയുന്ന രൂപത്തിലാവണം ഗാനങ്ങൾ.\n3. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.\n4. വിഷയം, പ്രാസം, താളം, സാഹിത്യം, ഭാവന എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"വിപ്ലവഗാന രചന"},{"id":"1d43abfc-e915-46ab-a75c-c8e52caf107b","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Magazine Layout","guidelines":"1. തന്നിരിക്കുന്ന മാറ്റർ ഉപയോഗിച്ച് മൂന്ന് പേജ് ലേ ഔട്ട് തയ്യാറാക്കുകയാണ് മത്സരം.\n2. Adobe Indesign/Affinity Publisher/Scribus എന്നിവയിൽ ഒരു സോഫ്‌ട്‌വെയർ ഉപയോഗിച്ചാണ് ലേ ഔട്ട് ചെയ്യേണ്ടത്.\n3. സീനിയർ വിഭാഗത്തിൽ ജില്ലാ, സംസ്ഥാന ഘടകങ്ങളിലാണ് മത്സരം.\n4. ലാപ്‌ടോപ്പ് മത്സരാർഥികൾ കൊണ്ട് വരേണ്ടതാണ്. ഇന്റർനെറ്റ് ഉപയോഗിക്കാവുന്നതാണ്.\n5. ഫോണ്ട്, ടൈപ്പ് സെറ്റിംഗ്, കോളം, ചിത്രസംയോജനം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"120m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മാഗസിൻ ലേ ഔട്ട്"},{"id":"20896ce7-a837-4a34-82ea-19974e478f37","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Mala Song","guidelines":"1. മുഹ്‌യിദ്ദീൻ മാല, രിഫാഈ മാല, നഫീസത്ത് മാല എന്നിവയിൽ നിന്ന് നറുക്കെടുപ്പിലൂടെ ഏതാണെന്ന് തീരുമാനിക്കണം.\n2. നിർദ്ദേശിച്ച മാലയിൽ നിന്ന് ഏത് ഭാഗവും അവതരിപ്പിക്കാം.\n3. സ്വരം, ശ്രുതിലയം, താളം, അംഗങ്ങൾ തമ്മിലുള്ള യോജിപ്പ് എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മാലപ്പാട്ട്"},{"id":"217db137-d038-4a27-a297-268ba7973297","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Hamd Urdu","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ഹംദ് ഉറുദു"},{"id":"22658222-5568-4ff1-ba0a-de02c4006b0f","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Language Game","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ഭാഷാ കളി"},{"id":"23dac4b3-44a1-440a-928a-949d7e87b072","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Vlog","guidelines":"1. നിശ്ചയിക്കപ്പെടുന്ന വിഷയത്തിൽ മത്സരാർഥി സ്വന്തം പ്രയത്നത്തിൽ യഥാർഥമായ ഒരു ലഘു വീഡിയോ ചെയ്ത് നൽകുകയാണ് വേണ്ടത്.\n2. മറ്റുള്ളവർ ചെയ്തതോ വെബ്‌സൈറ്റിൽ നിന്ന് എടുത്തതോ ആയ വീഡിയോകൾ സ്വീകാര്യമല്ല.\n3. വിഷയകേന്ദ്രീകൃതമായ വീഡിയോ, ലൊക്കേഷനിൽ നേരിട്ട് ചെന്ന് റെക്കോർഡ് ചെയ്യണം. റെക്കോർഡിങ്ങിനൊപ്പം തന്നെ വിശദീകരണവും നൽകുന്ന രീതിയാണ് വേണ്ടത്.\n4. വ്‌ളോഗ് നിർമാണത്തിൽ ബൈത്ത് കൂടി ഉൾക്കൊള്ളിക്കാവുന്നതാണ്.\n5. വ്‌ളോഗർക്കൊപ്പം വീഡിയോ എടുക്കുന്നതിൽ സഹായികളായി മറ്റാരും ഉണ്ടാവരുത്. പരമാവധി സമയം 7 മിനിട്ട് ആണ്.\n6. സെൽഫി സ്റ്റിക്, ഗിമ്പൽ എന്നിവയിലൊന്ന് ഉപയോഗിക്കാം. വീഡിയോയിൽ പുറമെ നിന്ന് ഇമേജുകളോ മറ്റോ ആഡ് ചെയ്യരുത്. ടെക്‌സ്റ്റ് നൽകാം.\n7. വീഡിയോ എടുത്ത ശേഷം വോയ്‌സ് ചേർക്കുകയോ ഡബ്ബിംഗ് നടത്തുകയോ ചെയ്യാൻ പാടില്ല.\n8. വിഷയത്തെ കൂടുതൽ ആഴത്തിൽ അവതരിപ്പിക്കാനും പരിഹാര നിർദ്ദേശങ്ങൾ ക്രിയാത്മകമായി മുന്നോട്ട് വെക്കാനും പരിശ്രമിക്കണം.\n9. ആശയ വ്യക്തത, അവതരണ മികവ്, ഇന്നൊവേഷൻ, ശബ്ദ ദൃശ്യ സമന്വയം, ശബ്ദ ദൃശ്യ നിലവാരം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"7m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"വ്‌ളോഗ്"},{"id":"271100aa-6b85-48db-a9f8-4b0bc5edb211","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Poetry Writing","guidelines":"1. ആശയം മത്സര ഹാളിൽ വെച്ച് നൽകണം.\n2. രചന 16 മുതൽ 20 വരെ വരിയിൽ ഒതുക്കുക.\n3. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.\n4. ഭാഷ, സർഗ്ഗാത്മകത, താളം, സൗന്ദര്യാത്മകത, പ്രതിപാദന രീതി എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കവിതാ രചന"},{"id":"298651d2-904e-4de5-9047-1ad49baa6704","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Qawwali","guidelines":null,"is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ഖവാലി"},{"id":"2a838355-a4a1-4dd5-89cd-5ba6df157033","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Project","guidelines":"1. ഡിവിഷൻ മുതലാണ് മത്സരം.\n2. സംസ്ഥാന കമ്മിറ്റി നൽകുന്ന വിഷയത്തെ ആസ്പദമാക്കിയാണ് പ്രോജക്ട് നിർമിക്കേണ്ടത്.\n3. നിശ്ചയിക്കപ്പെടുന്ന ദിവസത്തിനകം സെക്ടർ കമ്മിറ്റികൾ പ്രോജക്ട് ഡിവിഷൻ കമ്മിറ്റിക്ക് സമർപ്പിക്കണം. പ്രിന്റും എഴുത്തും സ്വീകാര്യമാണ്.\n4. അഞ്ച് അംഗങ്ങൾ അടങ്ങുന്ന സമിതിയാണ് പ്രോജക്ട് തയ്യാറാക്കേണ്ടത്.\n5. പ്രോജക്ട് മത്സരത്തിന് ജില്ലാ തലം മുതൽ വൈവ കൂടി ഉണ്ടായിരിക്കുന്നതാണ്. പ്രോജക്ട് തയ്യാർ ചെയ്ത അഞ്ച് അംഗ സംഘം വൈവ അറ്റൻഡ് ചെയ്യണം.\n6. വിവരശേഖരണം, വിഷയവിവരം എന്നിവയെ അടിസ്ഥാനപ്പെടുത്തി പ്രോജക്ടിൽ പരാമർശിച്ച കാര്യങ്ങളെ ആസ്പദമാക്കിയാണ് ചോദ്യങ്ങൾ ചോദിക്കുക.\n7. വൈവയെ അടിസ്ഥാനപ്പെടുത്തിയാണ് മാർക്കുകൾ നിശ്ചയിക്കേണ്ടത്.\n8. ഒന്നാം സ്ഥാനം ലഭിച്ച പ്രോജക്ട് ജില്ലയിലും ജില്ലയിൽ നിന്ന് തെരഞ്ഞെടുത്തത് സംസ്ഥാന മത്സരത്തിലേക്കും പരിഗണിക്കും.\n9. ആശയം, സംവിധാനം, മെത്തഡോളജി, സ്ഥിതി വിവരം, റഫറൻസ് എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"പ്രോജക്ട്"},{"id":"2bd29085-35ff-41ee-8b9c-948ff44372ca","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Caption Writing","guidelines":"1. നൽകപ്പെടുന്ന ചിത്രത്തിന് അനുയോജ്യമായ അടിക്കുറിപ്പ് നൽകുകയാണ് വേണ്ടത്.\n2. രണ്ട് ക്യാപ്‌ഷനുകൾ എഴുതാം. അതിൽ മികച്ചത് പരിഗണിക്കും.\n3. രണ്ടിൽ കൂടുതൽ ക്യാപ്‌ഷനുകൾ എഴുതാൻ പാടില്ല.\n4. ആശയ വ്യക്തത, ഭാവന, സംക്ഷിപ്തത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"15m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":110,"event_name_ml":"അടിക്കുറിപ്പ് മത്സരം"},{"id":"2e785056-8f7b-4759-9d3f-8192b189bae8","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Mushaara Al-Fiyya","guidelines":"1. അൽഫിയ ബൈതുകൾ മാത്രമാണ് അക്ഷരശ്ലോകത്തിലുണ്ടാവുക.\n2. മത്സരത്തിന് രണ്ട് റൗണ്ടുകളാണ് ഉണ്ടാകും.\n3. ആദ്യ റൗണ്ടിൽ ബൈതുകളുടെ മനഃപാഠമാണ് പരിശോധിക്കുക. വിധി കർത്താക്കൾ നിർദ്ദേശിക്കുന്ന ഭാഗം മുതൽ അൽഫിയ്യയിലെ ബൈതുകൾ തുടർച്ചയായി മത്സരാർഥികൾ ചൊല്ലണം. ബൈതുകൾ ചൊല്ലാൻ കഴിയാതെ വരുന്നവർ ഓരോരുത്തരായി പുറത്താകും.\n4. അവസാനം മൂന്ന് പേർ മാത്രം നില നിൽക്കുമ്പോൾ/നിശ്ചിത സമയം കഴിയുമ്പോൾ മത്സരത്തിന്റെ രണ്ടാം ഘട്ടത്തിലേക്ക് കടക്കും.\n5. രണ്ടാം റൗണ്ടിൽ വിധി കർത്താക്കൾ വ്യാകരണ നിയമങ്ങൾ പറയും. മത്സരാർഥി ഈ നിയമവുമായി ബന്ധപ്പെട്ട ബൈത്ത് ചൊല്ലണം.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മുശാഅറ അൽഫിയ്യ"},{"id":"2fef66c2-c26f-4499-8ecd-ac54d1ec806d","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Translation","guidelines":"1. നൽകപ്പെടുന്ന ഭാഗം ആശയം ചോരാതെ മലയാളത്തിലേക്ക് വിവർത്തനം നടത്തുകയാണ് വേണ്ടത്.\n2. പത്രവാർത്തകൾ പോലുള്ളവ ഒഴിവാക്കുക.\n3. ആശയ വ്യക്തത, സാഹിത്യഭംഗി, ശൈലി, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ട്രാൻസ്‌ലേഷൻ"},{"id":"35b236e1-3780-4db1-bf49-c89051b06b7c","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Group Song","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"സംഘഗാനം"},{"id":"3b521087-c658-4b98-a61d-2ff8f1255695","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Hadith Musabaka","guidelines":"1. ഹദീസ് വിജ്ഞാനത്തിലെ അറിവ് പരിശോധിക്കും വിധത്തിൽ ആയിരിക്കും ഈ മത്സരം.\n2. അർബഈ നന്നവി അടിസ്ഥാനമാക്കിയാണ് ഈ വർഷത്തെ മത്സരം.\n3. ആദ്യ റൗണ്ടിൽ നിർദ്ദിഷ്ട കിതാബിലെ ഹദീസുകൾ ഓതുകയാണ് വേണ്ടത്. ഒരാൾ ഓതിയത് പിന്നീട് ആവർത്തിക്കരുത്. ഇത് ഒരു എലിമിനേഷൻ റൗണ്ടാണ്. നിശ്ചിത സമയത്തിനകം ഓതാൻ കഴിയാത്തവർ പുറത്താകും. സമയം ജഡ്ജ്‌സ് തീരുമാനിക്കാം.\n4. രണ്ടാം ഘട്ടത്തിൽ പ്രസ്തുത കിതാബിലെ ഹദീസുകളുടെ ആശയം, റാവിമാരെ കുറിച്ചുള്ള വിവരങ്ങൾ, ഇസ്തിലാഹാത്ത് എന്നിവയെ അടിസ്ഥാനമാക്കിയുള്ള ചോദ്യങ്ങളാണ് ഉണ്ടാവുക.\n5. ചോദ്യങ്ങളുടെ എണ്ണം ജഡ്ജ്‌സ് തീരുമാനിക്കാവുന്നതാണ്. ആകെ ലഭിച്ച മാർക്ക് നോക്കിയാണ് വിജയിയെ തീരുമാനിക്കേണ്ടത്.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഹദീസ് മുസാബഖ"},{"id":"40dc6d18-6cbc-4315-b952-a16d069e6347","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Poster Designing","guidelines":"1. നൽകുന്ന മാറ്റർ ചാർട്ട് പേപ്പറിൽ ഡിസൈൻ ചെയ്യുകയാണ് മത്സരം.\n2. ഏത് നിറവുമാകാം. എണ്ണച്ചായം പാടില്ല.\n3. ആവശ്യമായ ചായം, ബ്രഷ് എന്നിവ മത്സരാർഥികൾ കൊണ്ടുവരണം.\n4. ഡമ്മി സൈസ് (45.5 x 58.5 cm) പോസ്റ്റർ പേപ്പറിലാണ് ഡിസൈൻ ചെയ്യേണ്ടത്.\n5. പേപ്പർ സംഘാടക സമിതി നൽകേണ്ടതാണ്.\n6. ആശയ വ്യക്തത, സംവിധാനം, ചായത്തിന്റെ മികവ്, ശൈലി, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"പോസ്റ്റർ ഡിസൈനിംഗ്"},{"id":"42cee00c-50d1-4f4d-9089-6b9949be5720","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Market Masters","guidelines":"1. 2 അംഗങ്ങൾ ഉള്ള ടീമായി നടക്കുന്ന ഒരു മാർക്കറ്റിംഗ് മത്സരമാണ് 'മാർക്കറ്റ് മാസ്റ്റേഴ്‌സ്'.\n2. മത്സരത്തിന്റെ 10 മിനിട്ട് മുൻപ് നൽകപ്പെടുന്ന ഒരു ഉൽപ്പന്നത്തെ അടിസ്ഥാനമാക്കി, അതിന്റെ ഗുണമേന്മയും വിപണന സാധ്യതകളും മുൻനിർത്തി പരസ്യ രൂപേണ അവതരിപ്പിക്കുകയാണ് മത്സരം.\n3. ഈ മത്സരം രണ്ട് ഘട്ടങ്ങളിലായാണ് നടക്കുന്നത്.\n4. ആദ്യ ഘട്ടത്തിൽ (അവതരണ ഘട്ടം) നൽകപ്പെട്ട ഉൽപ്പന്നത്തെക്കുറിച്ചുള്ള സമഗ്രമായ വിവരങ്ങൾ 5 മിനിറ്റിനുള്ളിൽ വിധികർത്താക്കൾക്ക് മുൻനിൽ അവതരിപ്പിക്കണം. കേവല വിവരണത്തിന് പകരം മറ്റ് സർഗ്ഗാത്മകമായ രീതികൾ ഉപയോഗിച്ച് ശ്രദ്ധ ആകർഷിക്കാൻ ടീമുകൾക്ക് സ്വാതന്ത്ര്യമുണ്ട്.\n5. അവതരണത്തിന് ശേഷം 5 മിനിറ്റ് നീണ്ടുനിൽക്കുന്ന വൈവ ഉണ്ടായിരിക്കും.\n6. ക്രിയാത്മകത, അവതരണ മികവ്, മാർക്കറ്റിനെ കുറിച്ചുള്ള അറിവ്, ടീം പങ്കാളിത്തം, ബ്രാൻഡിംഗ് & സ്‌ട്രാറ്റജി, മാർക്കറ്റിംഗ് പ്ലാൻ, Q&A Session എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മാർക്കറ്റ് മാസ്റ്റേഴ്‌സ്"},{"id":"4745be50-a9c3-4023-9aba-5d5aa63e95a0","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Daf","guidelines":"1. മത്സരത്തിൽ 10 പേരാണ് പങ്കെടുക്കേണ്ടത്.\n2. വേഷം: വെള്ള തുണി, വെള്ള ഷർട്ട്, വെള്ള തലപ്പാവ്. പരിഹാസ്യമായ വേഷങ്ങൾ പാടില്ല.\n3. അറബി ബൈത്തുകളോ മദ്‌ഹോ ആണ് ചൊല്ലേണ്ടത്.\n4. ബൈത്തിന്റെ വൈവിധ്യമാർന്ന ഈണങ്ങൾക്കനുസരിച്ച് ചാഞ്ഞും ചരിഞ്ഞും നിന്നും ഇരുന്നും വിവിധ താളങ്ങളിൽ അവതരിപ്പിക്കണം.\n5. നൃത്തമോ അമിതമായ ചുവടുകളോ പാടില്ല. തുകൽ ദഫുകളാണ് ഉപയോഗിക്കേണ്ടത്. പിന്നണി പാടില്ല.\n6. ബൈത്ത് (മദ്‌ഹ്), ഒറ്റമുട്ട്-മൂന്ന് മുട്ട്-അഞ്ച് മുട്ട്-കയ്യിൻ മുട്ട്-കോരി മുട്ട് ഇവയിൽ ഏതെങ്കിലും നാല് താളം, വാദ്യവാദനം, അവതരണം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ദഫ്"},{"id":"4791ea18-3c3a-4080-98b2-0021063f3e44","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Aravana Mutt","guidelines":null,"is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"അറവന മുട്ട്"},{"id":"49cc23c5-8290-4d39-9884-444090e8c6f9","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Maths Game","guidelines":"1. ഗണിതവുമായി ബന്ധപ്പെട്ട കുസൃതിക്കണക്കുകൾ, രസകരമായ ഗണിതപ്രശ്നങ്ങൾ, സംഖ്യാ പാറ്റേണുകൾ തുടങ്ങിയവയാണ് ഗണിതകേളിയിൽ ഉൾപ്പെടുത്തേണ്ടത്.\n2. അപ്പർ പ്രൈമറി വിഭാഗത്തിന്റെ മത്സര ഇനമായതിനാൽ യു.പി ക്ലാസിലെ ഗണിതാശയങ്ങൾ പരിഗണിച്ച് പരമാവധി 15 പ്രശ്നങ്ങൾ വരെ ഉൾപ്പെടുത്താവുന്നതാണ്. ചുരുങ്ങിയത് 10 പ്രശ്നമെങ്കിലും ഉണ്ടാവണം.\n3. ഓരോ പ്രശ്നത്തിന്റെയും നിലവാരമനുസരിച്ച് 1 മുതൽ 3 വരെ മാർക്ക് നൽകാവുന്നതാണ്.\n4. ഓരോ പ്രശ്നം അവതരിപ്പിക്കുമ്പോഴും അതിന്റെ മാർക്ക് അവതാരകൻ അറിയിക്കേണ്ടതാണ്.\n5. ലളിതമായും വ്യക്തമായും അവതരിപ്പിക്കണം. ഓരോ പ്രശ്നത്തിന്റെയും ഉത്തരങ്ങൾ അപ്പോൾ തന്നെ പരിശോധിക്കുകയും അർഹതപ്പെട്ട മാർക്കുകൾ നൽകുകയും വേണം.\n6. ആകെ മാർക്ക് പരിഗണിച്ചാണ് ഗ്രേഡ് നൽകേണ്ടത്.\n7. കണ്ടെത്തുന്ന ചോദ്യങ്ങൾ വ്യക്തവും കൃത്യവുമായിരിക്കണം. അവതാരകൻ നൽകുന്ന ഉത്തരം തന്നെ എഴുതണമെന്ന് നിർബന്ധിക്കരുത്. പ്രശ്നത്തിൽ ശരിയായ പരിഹാരമായി വരുന്ന മറ്റ് ഉത്തരങ്ങൾ എഴുതിയാൽ മാർക്ക് നൽകണം. ഇങ്ങനെയുള്ള ഉത്തരങ്ങൾ പറയാനും അതിന്റെ യുക്തി അവതരിപ്പിക്കാനും മത്സരാർഥികൾക്ക് അവസരം നൽകേണ്ടതാണ്.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഗണിതകേളി"},{"id":"4b046809-bf19-4bfa-a755-5e15426514c9","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Digital Illustration","guidelines":"1. അഡോബ് ഇല്ലസ്‌ട്രേറ്റർ, Inkscape എന്നീ സോഫ്‌ട്‌വെയറുകളിൽ ഒന്ന് ഉപയോഗിച്ച് നൽകപ്പെടുന്ന വിഷയത്തിൽ ലോഗോ ഡിസൈൻ ചെയ്യുകയാണ് വേണ്ടത്.\n2. ലോഗോയോടൊപ്പം സൃഷ്ടിയുടെ മോണോഗ്രാം കൺസെപ്‌റ്റ് കൂടി ചേർക്കണം.\n3. ലോഗോയിൽ ഉപയോഗിച്ച മുഴുവൻ സൂചകങ്ങളും രൂപപ്പെടുത്തിയ രീതി മോണോഗ്രാം കൺസെപ്‌റ്റിൽ ചേർത്തിരിക്കണം.\n4. ആശയം ഏറ്റവും പൂർണതയിലും ലളിതമായും അവതരിപ്പിക്കണം.\n5. ലോഗോ ഐക്കണോഗ്രാഫിക് അല്ലെങ്കിൽ ടൈപ്പോഗ്രാഫിക്ക് ആവാം. പുറമെ നിന്നുള്ള ചിത്രങ്ങൾ ഒന്നും ഉപയോഗിക്കരുത്.\n6. ആശയ വ്യക്തത, വ്യത്യസ്ത രീതികളിൽ/പ്രതലങ്ങളിൽ ഉപയോഗിക്കാനുള്ള ക്ഷമത, വരയിലെ ലാളിത്യം, ആശയ വൈവിധ്യം, മൗലികത, ബാലൻസ് & പ്രൊപ്പോർഷൻ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഡിജിറ്റൽ ഇല്ലസ്‌ട്രേഷൻ"},{"id":"4e89b499-bfaa-4ee7-b477-cad1d72fd6aa","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"DEFAULT_CREATIVE","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":null},{"id":"4fdaec4b-a974-4cee-a277-130a72e1d1fd","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Language Pro","guidelines":"1. ഭാഷ ശേഷി അളക്കാൻ കാമ്പസ് ലെവലിൽ നടത്താവുന്ന ഈ ഓഫ്‌സ്റ്റേജ് മത്സരം മൂന്ന് തരം ചോദ്യങ്ങൾ ഉൾപ്പെട്ടതാണ്.\n2. ഒരു കോം‌പ്ലക്സ് സെന്റൻസ് കൊടുക്കുകയും അതിലെ വ്യക്തവും അവ്യക്തവുമായ വ്യാകരണ ഘടകങ്ങൾ തിരിച്ചറിയാനുള്ള ശേഷി അളക്കുകയും ചെയ്യുക. സെന്റൻസിലെ ആശയം വ്യാകരണ അടിസ്ഥാനത്തിൽ സമർഥിക്കാനുള്ള ശേഷി അനുസരിച്ച് മാർക്ക് നൽകാം.\n3. ഒരു വലിയ ആശയം വ്യാകരണ സ്ഖലിതം സംഭവിക്കാതെ ഏറ്റവും വലിയ വാക്യത്തിൽ ഇടക്ക് ഫുൾസ്റ്റോപ്പ് വരാതെ അവതരിപ്പിക്കുക. സെന്റൻസിന്റെ വലിപ്പം അനുസരിച്ച് മാർക്ക് നൽകാം.\n4. ഒരൊറ്റ ആശയം ഒന്നിലധികം സെന്റൻസുകളിലായി അവതരിപ്പിക്കുക. സെന്റൻസുകളുടെ എണ്ണം അനുസരിച്ച് മാർക്ക് നൽകാം.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ലാംഗ്വേജ് പ്രോ"},{"id":"52192baa-bd76-49b5-97cc-4c60ec132997","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Bhakthi Ganam","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ഭക്തിഗാനം"},{"id":"5486b47a-6d71-49fd-831a-26376f3f2312","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Feature Writing","guidelines":"1. മത്സര ഹാളിൽ വെച്ച് നൽകുന്ന വിഷയത്തിൽ വിവരണാത്മക ശൈലിയിൽ മൂന്ന് പേജിൽ കവിയാത്ത ഫീച്ചർ തയാറാക്കണം.\n2. രചന 4 പുറത്തിൽ കവിയരുത്.\n3. വിഷയവുമായുള്ള ബന്ധം, ഫീച്ചർ ശൈലി, ഭാഷ, വിവരണാത്മകത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഫീച്ചർ റൈറ്റിംഗ്"},{"id":"59773606-0b3d-4a56-8cf6-7749ac314afa","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"AI Prompting","guidelines":"1. AI ടൂളുകൾ ഉപയോഗിച്ച് ആവിശ്യമായ പ്രോംപ്‌റ്റുകൾ കൊടുത്ത് നൽകപ്പെടുന്ന വിഷയത്തിൽ ഒരു Comprehensive Solution/Complete Package തയ്യാറാക്കുന്ന വ്യക്തിഗത മത്സരമാണിത്.\n2. അര മണിക്കൂർ ആണ് ആകെ സമയം. മത്സരാർഥികൾക്ക് AI ടൂളുകൾ ഉപയോഗിക്കാൻ ഒരു ലാപ്‌ടോപ്പ് അല്ലെങ്കിൽ മൊബൈൽ ഫോൺ ഉപയോഗിക്കാം.\n3. ഫൈനൽ ഔട്ട്‌പുട്ട് Word/PDF/സമാനമായ ഫോർമാറ്റുകളിൽ സെറ്റ് ചെയ്ത് വിധിനിർണ്ണയത്തിനായി കൈമാറണം.\n4. പ്രോംപ്‌റ്റുകളും റെസ്‌പോൺസും അടങ്ങുന്ന ചാറ്റ് ഹിസ്റ്ററിയും ഫൈനൽ പ്രൊഡക്ടും വിധി നിർണ്ണയത്തിനായി നൽകണം.\n5. പ്രോംപ്‌റ്റുകളുടെ തിരഞ്ഞെടുപ്പും വ്യത്യസ്തതയും പാക്കേജിൽ അടങ്ങിയിട്ടുള്ള ഐറ്റംസിന്റെ ഡൈവേഴ്‌സിറ്റിയും ഫൈനൽ പ്രൊഡക്ടിന്റെ നിലവാരത്തോടൊപ്പം വിധി നിർണ്ണയിക്കുമ്പോൾ പരിഗണിക്കണം.\n6. Diversity of prompts, Clarity of prompt objectives, Effective use of AI-generated content, Quality of the final output, Diversity of Items included in the Kit/Package എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"എഐ പ്രോംപ്റ്റിംഗ്"},{"id":"5d0d3221-83a2-4a7e-8335-ed1bef59f554","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Mappila Song","guidelines":"1. തനത് മാപ്പിളപ്പാട്ടുകളാണ് ആലപിക്കേണ്ടത്. സലീഖത്ത് പടപ്പാട്ട് എന്നിവ അനുവദനീയമല്ല.\n2. മാപ്പിളപ്പാട്ടിന്റെ തനിമക്ക് ആധാരമായ ഇശൽ, പ്രാസം, മാപ്പിള സാഹിത്യം/അറബി മലയാള സാഹിത്യം എന്നീ മൂന്ന് നിയമങ്ങളും പാലിക്കപ്പെടണം.\n3. സ്വരം, സാഹിത്യം, മാപ്പിളത്തനിമ, താളം, ശ്രുതിലയം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മാപ്പിള പ്പാട്ട്"},{"id":"6457d8c4-5079-473b-ad06-8b6ce4f9f8db","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Revolutionary Song","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"വിപ്ലവ ഗാനം"},{"id":"6a3ffffe-655b-44eb-b0c1-87575c34b128","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"AI Poetry Writing","guidelines":"1. AI ടൂളുകൾ ഉപയോഗിച്ച് ആവശ്യമായ പ്രോംപ്‌റ്റുകൾ നൽകി ഇംഗ്ലീഷിൽ കവിത നിർമിക്കുന്നതാണ് മത്സരം.\n2. AI റെസ്‌പോൺസിൽ അനിവാര്യമായ കൈകടത്തലുകൾ നടത്തി പാകപ്പെടുത്താവുന്നതാണ്.\n3. മത്സരാർഥികൾക്ക് AI ടൂളുകൾക്കായി ഒരു മൊബൈൽ ഫോൺ അല്ലെങ്കിൽ ലാപ്‌ടോപ്പ് ഉപയോഗിക്കാം.\n4. ഉപയോഗിക്കുന്ന ടൂളുകൾ ലോഗ് ഔട്ട് ചെയ്ത് പ്രീവിയസ് ചാറ്റ്സ് ക്ലിയർ ചെയ്ത് ആയിരിക്കണം യൂസ് ചെയ്യേണ്ടത്.\n5. ഉപയോഗിച്ച AI ടൂലും പ്രോംപ്‌റ്റുകളും റെസ്‌പോൺസും അടങ്ങുന്ന ചാറ്റ് ഹിസ്റ്ററിയും ഫൈനൽ കവിതയും (PDF ഫോർമാറ്റിൽ) വിധിനിർണ്ണയത്തിനായി നൽകണം.\n6. രചന 16-20 വരെ വരിയിൽ ഒതുക്കണം.\n7. ഭാഷ, സർഗ്ഗാത്മകത, താളം, സൗന്ദര്യാത്മകത, പ്രതിപാദന രീതി, പ്രോംപ്‌റ്റിന്റെ ക്രിയേറ്റിവിറ്റി എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"AI കവിതാ രചന"},{"id":"6e3d9e76-1167-4e24-844e-46f9317856a1","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"DEFAULT_PERFORMANCE","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":null},{"id":"70664d93-fee3-47e9-8416-a8cfb49e2048","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Speech","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"പ്രസംഗം"},{"id":"75e53659-dc3f-44cc-a07c-7f8aa1d2db9a","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Essay","guidelines":"1. മത്സര ഹാളിൽ വെച്ച് വിഷയം നൽകും. വിഷയം ബോർഡിൽ എഴുതുകയോ സ്ലിപ്പിൽ ഓരോരുത്തർക്കും നൽകുകയോ വേണം.\n2. രചന 4 പുറത്തിൽ കവിയരുത്.\n3. ഭാഷാ ലാളിത്യം, വസ്തുതകളുടെ വിന്യാസം, അവതരണ മികവ്, വിഷയത്തിലുള്ള അറിവ്, റഫറൻസ് എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഉപന്യാസം"},{"id":"7956f322-caab-49b8-884e-ddc552b24224","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Moulood Recitation","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"മൗലൂദ് പാരായണം"},{"id":"79fe62f2-1d85-49ff-a3ac-a54e6b802f02","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Sudoku","guidelines":"1. മത്സരം നിയന്ത്രിക്കുന്ന മാസ്റ്റർ നൽകുന്ന 9x9 ഗ്രിഡിൽ 1 മുതൽ 9 വരെയുള്ള സംഖ്യകൾ പൂരിപ്പിക്കുക എന്നതാണ് സുഡോക്കുവിന്റെ രീതി.\n2. ഓരോ വരിയിലും കോളത്തിലും 3x3 ബ്ലോക്കിലും ഓരോ സംഖ്യയും ഒരിക്കൽ മാത്രമേ ഉള്ളൂ എന്ന് ഉറപ്പ് വരുത്തുക.\n3. പരമാവധി സമയം 30 മിനിട്ടാണ്. ആദ്യം പൂർത്തിയാകുന്നതിനനുസരിച്ചാണ് വിജയികളെ തെരഞ്ഞെടുക്കേണ്ടത്.\n4. സെക്ടർ തലം മുതൽ ഈസി, മീഡിയം, ഹാർഡ് എന്നിങ്ങനെ രണ്ടോ മൂന്നോ ഘട്ടങ്ങളിലായി ആവശ്യത്തിനനുസരിച്ച് നടത്താവുന്നതാണ്.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സുഡോക്കു"},{"id":"7b43cc44-2355-48d0-8c8b-d2d83dd451c3","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Wall Writing","guidelines":"1. നൽകുന്ന വിഷയം നിശ്ചിത വലിപ്പമുള്ള ചുമരിൽ/ബോർഡിൽ ബ്രഷ് ഉപയോഗിച്ച് താൽപ്പര്യമുള്ള കളറുകളിൽ എഴുതുന്ന രീതിയാണ് മത്സരം.\n2. എഴുതാനുള്ള ബ്രഷ്, സ്റ്റൈനർ, മറ്റ് സാമഗ്രികൾ മത്സരാർഥികൾ കൊണ്ട് വരണം.\n3. മത്സരം നടക്കുന്ന സ്ഥലത്തോ പരിസരത്തോ ഉള്ള ചുമരുകൾ പ്രോഗ്രാം കമ്മിറ്റി തന്നെ കണ്ടെത്തി നേരത്തെ തന്നെ വൈറ്റ് വാഷ് ചെയ്ത് അംഗങ്ങൾക്ക് വേണ്ടി നിശ്ചിത ഏരിയ മാർക്ക് ചെയ്ത് വെക്കണം.\n4. എല്ലാ മത്സരാർഥികൾക്കും തുല്യ അളവിലുള്ള ചുമരുകളാണ് നൽകേണ്ടത്. ചുമരുകൾ പലയിടത്തായാലും വിരോധമില്ല.\n5. ചുമർ ലഭ്യമല്ലാത്ത സ്ഥലങ്ങളിൽ 6x4 വലിപ്പത്തിൽ തുണി ബോർഡ് വൈറ്റ് ഡിസ്ടമ്പർ ചെയ്ത് മത്സരത്തിന് വേണ്ടി തയ്യാറാക്കാവുന്നതാണ്.\n6. സംവിധാനം, ചായത്തിന്റെ മികവ്, ശൈലി, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ചുമരെഴുത്ത്"},{"id":"7c5fca0e-d9d7-46a6-8e32-aaa6473c48f0","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Mappila Song Writing","guidelines":"1. നൽകപ്പെടുന്ന വിഷയത്തിൽ വൃത്തവും പ്രാസവും തനതു മാപ്പിളപ്പാട്ടിന്റെ മറ്റ് നിയമങ്ങളും പാലിച്ച് പുതിയ രചന നിർവഹിക്കണം.\n2. രചനയിൽ ഇശൽ ചേർക്കേണ്ടതാണ്.\n3. 12 മുതൽ 16 വരെ വരിയിൽ ഉൾകൊള്ളിക്കുക.\n4. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.\n5. പ്രാസ നിയമങ്ങൾ, വിഷയം, സാഹിത്യം, താളം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മാപ്പിളപ്പാട്ടു രചന"},{"id":"7df6f625-4265-4b09-b137-0b556d10abe1","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Risala Quiz","guidelines":"1. റിസാല വാരിക, റിസാല അപ്‌ഡേറ്റ് എന്നിവ ആസ്പദമാക്കിയാണ് മത്സരം സംഘടിപ്പിക്കേണ്ടത്.\n2. ലക്കം 1624 മുതൽ അതത് സാഹിത്യോത്സവ് നടക്കുന്നതുവരെയുള്ള റിസാലയാണ് പരിഗണിക്കേണ്ടത്.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"റിസാല ക്വിസ്"},{"id":"7f8bd63d-e854-494f-bd14-e64a24ac9726","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Political Debate","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"രാഷ്ട്രീയ സംവാദം"},{"id":"816b6278-230b-4155-8dce-7a17411dfa71","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Story Writing","guidelines":"1. ആശയം മത്സര ഹാളിൽ വെച്ച് നൽകണം. കൂൾ ഓഫ് ടൈം കഴിഞ്ഞാലാണ് എഴുതാനുള്ള പേപ്പർ നൽകേണ്ടത്.\n2. 4 പുറത്തിൽ കവിയരുത്.\n3. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.\n4. ഭാഷ, സർഗ്ഗാത്മകത, ആവിഷ്കാര രീതി, സൗന്ദര്യാത്മകത, പ്രതിപാദന രീതി എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കഥാ രചന"},{"id":"81d6eb5c-3f51-4737-9974-7e879fd213c1","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Calligraphy","guidelines":"1. മത്സര ഹാളിൽ നൽകുന്ന അറബിക് വാചകം വാക്ക് കാലിഗ്രഫിയിലേക്ക് പകർത്തുകയാണ് വേണ്ടത്.\n2. എഴുതേണ്ടത് ഖത്ത് സുലുസ് ലിപിയിൽ ആയിരിക്കണം.\n3. ഉപയോഗിക്കുന്ന പേനയുടെ കനം 8mm മുതൽ 10mm വരെ ആയിരിക്കണം.\n4. മത്സര ജഡ്ജ്‌മെന്റ് ചെയ്യുന്നത് പൂർണമായും കാലിഗ്രഫിയുടെ നിയമം അനുസരിച്ചായിരിക്കും.\n5. മത്സരത്തിന് A3 പേപ്പർ സൈസിൽ ആർട്ട് ഗ്ലോസി/ആർട്ട് മാറ്റ് പേപ്പറാണ് ഉപയോഗിക്കേണ്ടത്.\n6. നിയമങ്ങൾ, രൂപം കലാപരത, എഴുത്തിലെ കൃത്യത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കാലിഗ്രഫി"},{"id":"83c0701b-a4f5-42ac-a96e-21ec2e45d603","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Podcast","guidelines":"1. 15 മിനിറ്റ് മുൻപ് നൽകുന്ന സമകാലിക വിഷയങ്ങളിൽ 5 മിനിറ്റ് ദൈർഘ്യമുള്ള പോഡ്‌കാസ്റ്റ് ലൈവായി അവതരിപ്പിക്കുന്നതാണ് മത്സരം.\n2. മത്സരാർഥികളുടെ സംസാര ശേഷി, ആകർഷക ഭാഷ, ശരീര ഭാഷ, ശാന്തമായ ശൈലി (സംയമനം), ആശയ വിനിമയം, സമയം എന്നിവ പരിഗണിച്ചാണ് മാർക്ക് നൽകേണ്ടത്.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"പോഡ്‌കാസ്റ്റ്"},{"id":"88d911d5-de6c-4b44-9ead-89a6eab3546d","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Qaseedah Recitation","guidelines":"1. ബുർദ, വിത്‌രിയ്യ, അല്ലഫൽ അലിഫ്, മഹ്‌ളറതുൽ ബദ്‌രിയ്യ എന്നീ ഖസ്വീദകളിൽ നിന്നും നറുക്കിട്ട് ലഭിക്കുന്നവയിലെ വിധികർത്താക്കൾ നിശ്ചയിക്കുന്ന ഭാഗമാണ് പാരായണം ചെയ്യേണ്ടത്.\n2. അക്ഷരസ്ഫുടത, അവതരണ രീതി, ശ്രുതിലയം, അംഗങ്ങൾ തമ്മിലുള്ള യോജിപ്പ്, താളം-ഖസീദ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഖസ്വീദ പാരായണം"},{"id":"8bf137a4-cd96-41dd-b74f-c862e2077f12","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Spelling Bee","guidelines":"1. ഇംഗ്ലീഷ് വാക്കുകളുടെ സ്‌പെല്ലിംഗ് അടിസ്ഥാനപ്പെടുത്തിയുള്ള മത്സരമാണ് സ്‌പെല്ലിംഗ് ബീ.\n2. യോഗ്യനായ ഒരാളെ (സ്‌പെല്ലിംഗ് ബീ മാസ്റ്റർ) മത്സര നിയന്ത്രണത്തിന് ഏൽപ്പിക്കുക. ഇംഗ്ലീഷ് ഉച്ചാരണം അറിയുന്ന ആളായിരിക്കണം.\n3. രണ്ട് ഘട്ടങ്ങളായാണ് മത്സരം നടക്കേണ്ടത്.\n4. ലെവൽ 1: ഇംഗ്ലീഷ് വാക്കുകളുടെ ഒരു ലിസ്റ്റ് തയ്യാറാക്കുക. വാക്കുകളുടെ എണ്ണം മാസ്റ്റർക്ക് തീരുമാനിക്കാം. ലിസ്റ്റിലെ വാക്കുകൾ മാസ്റ്റർ ഉച്ചരിക്കുക. ഉച്ചരിച്ച വാക്കിന്റെ സ്‌പെല്ലിംഗ് മത്സരാർഥി എഴുതുക. വാക്കുകളുടെ സംശയം ദൂരീകരിക്കാൻ അവയുടെ ചെറിയ വിവരണം, ഉദ്ഭവം തുടങ്ങിയവ സൂചിപ്പിക്കാവുന്നതാണ്.\n5. ലെവൽ 2: വാക്കുകളെ കുറിച്ചുള്ള ചോദ്യങ്ങൾ തയ്യാറാക്കുക. അവയുടെ ഉത്തരമായി നാല് ഓപ്ഷനുകൾ കൊടുക്കുക. ഓപ്ഷനുകളിൽ നിന്ന് ശരിയായ ഉത്തരം മത്സരാർഥി സെലക്ട് ചെയ്തു എഴുതുക. രണ്ട് ഘട്ടങ്ങളിലുമായി ഏറ്റവും കൂടുതൽ സ്‌കോർ ലഭിച്ച മത്സരാർഥിയാണ് വിജയി.","is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സ്‌പെല്ലിംഗ് ബീ"},{"id":"92be531d-8b49-44b3-aa27-69cf688983a4","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Watercolour","guidelines":"1. നൽകുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്.\n2. ആവശ്യമായ പെൻസിൽ, കളറുകൾ, ബ്രഷ് തുടങ്ങിയവ മത്സരാർഥികൾ കരുതണം.\n3. A4 വലുപ്പത്തിലുള്ള പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്. പേപ്പർ പ്രോഗ്രാം കമ്മിറ്റി നൽകണം.\n4. ലോവർ പ്രൈമറി, അപ്പർ പ്രൈമറി ഒഴികെ വിഭാഗങ്ങളിൽ ചിത്രരചന പെൻസിൽ, ചിത്രരചന ജലച്ചായം മത്സരങ്ങളിൽ വരക്കുന്ന ചിത്രങ്ങളുടെ ആശയം എഴുതിച്ചേർക്കേണ്ടതാണ്.\n5. ആവശ്യമായ A4 ഷീറ്റ് ഉപയോഗിക്കാവുന്നതാണ്.\n6. ആശയ വ്യക്തത, സംവിധാനം, ചായത്തിന്റെ മികവ്, ശൈലി, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ജലച്ചായം"},{"id":"96527c07-559c-4b3e-b8ea-4c643d890cad","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Reading Competition","guidelines":null,"is_default":true,"time_limit":"3m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"വായനാ മത്സരം"},{"id":"9d3f1132-d37b-4ae9-a506-018f7769ad96","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"News Writing","guidelines":"1. നൽകപ്പെടുന്ന ഒരു വിഷയം/ആശയത്തെ അടിസ്ഥാനമാക്കി പത്രത്തിലേക്ക് ഒരു വാർത്ത തയ്യാറാക്കുക.\n2. വാർത്തയുടെ ഘടന, ശീർഷകം-മികവ്, ഭാഷയിലെ ലാളിത്യം, ഉള്ളടക്കത്തിലെ വ്യക്തത, വസ്തുതകൾ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"20m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ന്യൂസ് റൈറ്റിംഗ്"},{"id":"9d4eab72-e8c4-4c50-b071-8eb22693ea75","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Poem Recitation / Arabic Poem","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"കവിതാ പാരായണം"},{"id":"a3a363f7-bdf8-48b8-b9fb-b434c3e7ff26","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Quiz","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ക്വിസ്"},{"id":"a96d25bf-1206-4793-84d2-27bfc9c6a01b","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Socio Synapse","guidelines":"1. 15 മിനിറ്റ് മുൻപ് നൽകുന്ന ഒരു പ്രമേയത്തെയോ ദൃശ്യത്തെയോ ആസ്പദമാക്കി തൽസമയം കഥ രൂപപ്പെടുത്തി അവതരിപ്പിക്കുകയാണ് വേണ്ടത്.\n2. മത്സരാർഥികളുടെ ചിന്താ ശേഷി, ദാർശനികമായ ആഴം, മികച്ച ആഖ്യാന ശൈലി എന്നിവ പരിഗണിച്ചാണ് മാർക്ക് നൽകേണ്ടത്.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സോഷ്യോ സിനാപ്സ്"},{"id":"ba748a52-0f0b-4b92-b143-01faa632aa4d","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Devotional Song","guidelines":"1. വിശ്വാസം, കർമ്മങ്ങൾ, ആചാരങ്ങൾ തുടങ്ങിയ വിഷയങ്ങളെ ആസ്പദമാക്കിയുള്ള ഇസ്‌ലാമിക ഭക്തിഗാനങ്ങളാണ് അവതരിപ്പിക്കേണ്ടത്.\n2. ഗാനങ്ങളിലെ പരാമർശിത വിഷയങ്ങൾ ആധികാരികമായിരിക്കണം.\n3. സാഹിത്യം, ശ്രുതിലയം, താളം, സ്വരം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഭക്തി ഗാനം"},{"id":"ba9e1158-6a56-40b7-8844-383b44345db2","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Reading","guidelines":"1. അതത് ഭാഷയിലെ ഫിക്ഷൻ പുസ്തകങ്ങളിൽ നിന്ന് വിധികർത്താക്കൾ നിർണയിച്ച് നൽകുന്ന ഭാഗം വായിക്കുക.\n2. മത്സരത്തിന് 10 മിനിട്ട് മുമ്പ് ഓരോ മത്സരാർഥിക്കും ഭാഗം നിർണയിച്ച് നൽകണം.\n3. വായനയുടെ താളം, അക്ഷരസ്ഫുടത, ആശയ ഗ്രഹണം, ശബ്ദ ക്രമീകരണം, ഭാവ വ്യത്യാസം എന്നിവ വിലയിരുത്തുക.\n4. സമയപരിധി 3 മിനിട്ട് ആണ്.","is_default":true,"time_limit":"3m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"വായന"},{"id":"bc44a67c-20fd-417f-a65b-c7f020907ae9","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Origami","guidelines":"1. കടലാസുകൾ മടക്കി വിവിധ രൂപങ്ങൾ സൃഷ്ടിക്കുന്ന മത്സരമാണിത്.\n2. ഒരു കടലാസ് മുറിക്കാതെയോ ഒട്ടിക്കാതെയോ വസ്തുക്കളുടെ രൂപങ്ങൾ വിവിധ ജ്യാമിതീയ രീതികളിൽ മടക്കിയാണ് രൂപങ്ങൾ നിർമിക്കേണ്ടത്.\n3. മനുഷ്യരുടെയോ മറ്റ് ജീവജാലങ്ങളുടെയോ രൂപങ്ങൾ ആവരുത്.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഒറിഗാമി"},{"id":"bf4970d2-48a9-4936-9403-b6ee549b7e93","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Ideathon","guidelines":"1. മത്സരത്തിന്റെ ഒരു മണിക്കൂർ മുമ്പ് നൽകപ്പെടുന്ന പ്രശ്നങ്ങളുടെ/വിഷയങ്ങളുടെ സൊല്യൂഷൻ എന്ന നിലക്കാണ് വ്യത്യസ്ത ആശയങ്ങൾ/ഐഡിയകൾ രൂപപ്പെടുത്തി ജൂറിക്ക് മുന്നിൽ അവതരിപ്പിക്കേണ്ടത്.\n2. മൂന്ന് അംഗങ്ങൾ ഉള്ള ടീം ആയിട്ടാണ് മത്സരിക്കേണ്ടത്.\n3. ഒരു ടീമിന് ആവശ്യമെങ്കിൽ ഒരു ഫോൺ & ലാപ്‌ടോപ്പ് ഉപയോഗിക്കാവുന്നതാണ്. പുറത്തുള്ളവരുമായി ആശയ വിനിമയം നടത്തുന്നത് ശ്രദ്ധിക്കണം.\n4. സ്ലൈഡുകൾ, ദൃശ്യങ്ങൾ, സ്‌കെച്ചുകൾ, പ്രോട്ടോടൈപ്പ് മാതൃകകൾ, സ്റ്റാറ്റിസ്‌റ്റിക്‌സ് എന്നിവയുടെ സഹായത്തോടെ ഐഡിയ/ആശയങ്ങൾ അവതരിപ്പിക്കാവുന്നതാണ്.\n5. ടീമിലെ എല്ലാവരും അവതരണത്തിൽ പങ്കാളികളായിരിക്കണം. അവതരണത്തിന് 10 മിനിറ്റും വൈവക്ക് 5 മിനിറ്റുമാണ് സമയം.\n6. അവതരിപ്പിക്കപ്പെടുന്ന ഐഡിയകളോട് പ്രതികരിച്ച് ജൂറി സംശയങ്ങൾ ചോദിക്കുകയും ചോദ്യങ്ങൾക്ക് മറുപടി നൽകുകയും വേണം.\n7. ഇന്നൊവേഷൻ, പ്രായോഗികത, അവതരണ വ്യക്തത, ടീം പങ്കാളിത്തം, സാമൂഹ്യ/വ്യാവസായിക സ്വാധീനം, വൈവ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"15m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഐഡിയതോൺ"},{"id":"bf68903a-3e18-4239-a758-6f8d2a28e7a9","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"DPR Presentation","guidelines":"1. സംസ്ഥാന തലത്തിൽ മാത്രമാണ് ഈ മത്സരമുണ്ടാകുക.\n2. നേരത്തെ നിർണയിച്ച് നൽകുന്ന വിഷയങ്ങളിലൊന്നിൽ വിശദമായ ഒരു പ്രോജക്ട് തയ്യാറാക്കി അവതരിപ്പിക്കുകയാണ് മത്സരം.\n3. കമ്പനികൾ, സ്റ്റാർട്ടപ്പുകൾ എന്നിവയുടെ പ്രസന്റേഷന് സമാനമായ രീതിയിൽ പവർ-പോയിന്റ് പ്രസന്റേഷന്റെ സഹായത്തോടെയാണ് ഇത് നടക്കേണ്ടത്.\n4. നാല് പേരുടെ ഒരു ടീം ആണ് ഈ മത്സരത്തിൽ പങ്കെടുക്കേണ്ടത്. ഒരാൾ പവർ-പോയിന്റ് പ്രസന്റേഷൻ ഓപ്പറേറ്ററും കൂടി ആയി പ്രവർത്തിക്കുകയും 4 പേരും അവതരണത്തിൽ ഭാഗവാക്കാവുകയും വേണം.\n5. ഒരു ടീമിന് 20 മിനിട്ട് ആണ് സമയം ലഭിക്കുക.\n6. സാങ്കേതിക സംവിധാനങ്ങളുടെ പ്രയോഗം, സാമ്പത്തിക ക്ഷമത, റിസ്‌ക് അസസ്‌മെന്റ്, കമ്മ്യൂണിക്കേഷൻ പ്ലാൻ, അവതരണ മികവ് എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"20m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഡി പി ആർ പ്രസന്റേഷൻ"},{"id":"bf9f84ad-354f-4077-80db-29a355646318","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Slogan Writing","guidelines":"1. നൽകപ്പെടുന്ന വിഷയത്തിൽ 20 വരിയിൽ കവിയരുതെ മുദ്രാവാക്യം തയ്യാറാക്കുക.\n2. ഭാഷ, സൗന്ദര്യാത്മകത, താളം, പ്രതിപാദന രീതി എന്നിവ വിലയിരുത്തുക.\n3. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മുദ്രാവാക്യ രചന"},{"id":"c97e44d8-eac7-4901-8ea8-593c524c7609","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Story Narration","guidelines":"1. ധർമ ബോധം വളർത്താൻ സഹായകമാവുന്ന ഇസ്‌ലാമിക കഥകളാണ് അവതരിപ്പിക്കേണ്ടത്.\n2. ആഭാസകരമായ രീതിയിലുള്ള ആംഗ്യങ്ങൾ ഉപേക്ഷിക്കുക.\n3. ശ്രദ്ധേയമായ ചരിത്ര കഥകൾ അവതരിപ്പിക്കുക. നാടൻ ശൈലികൾ കഥ പറയലിൽ കടന്നു വരരുത്.\n4. ഇത്തവണ അവതരിപ്പിക്കുന്ന കഥകൾ എൽ പി വിഭാഗത്തിന് അബൂബക്കർ സ്വിദ്ദീഖ്(റ)ന്റെ ജീവിതവും യു പി വിഭാഗത്തിന് ഹിജ്‌റക്ക് മുമ്പുള്ള പ്രവാചക ചരിത്രവുമായി ബന്ധപ്പെട്ടതും ആവാൻ ശ്രദ്ധിക്കുക.\n5. ഡിവിഷൻ തലം മുതൽ പ്രസ്തുത ഭാഗങ്ങൾ മാത്രമേ കഥയായി പരിഗണിക്കുകയുള്ളൂ.\n6. കഥയുടെ ആവിഷ്കാരത്തിലും അവതരണത്തിലും പുതുമകൾ കൊണ്ടുവരാൻ ശ്രദ്ധിക്കേണ്ടതാണ്.\n7. മനഃപാഠം, ഉച്ചാരണ ശുദ്ധി, അവതരണ രീതി, ഭാവ പ്രകടനം, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കഥാ കഥനം"},{"id":"cd9e86f8-d955-4d46-8b47-6a72a742e16b","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"News Reading","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"വാർത്താ വായന"},{"id":"cf7d8cc6-3a44-4bce-929f-e30e8bdf5a34","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Book Tale","guidelines":"1. നിർദ്ദേശിക്കുന്ന പുസ്തകത്തിന്റെ ആശയം സ്‌റ്റോറി ടെല്ലിംഗ് രീതിയിൽ അവതരിപ്പിക്കുന്ന 5 മിനിറ്റിലൊതുങ്ങുന്ന വീഡിയോ തയ്യാറാക്കലാണ് മത്സരം.\n2. പുസ്തകത്തിന്റെ ചരിത്രത്തെയും രാഷ്ട്രീയത്തെയും സമകാലിക പ്രസക്തിയെയും അദ്ധ്യാപനത്തെയും ആഴത്തിലും ലളിതമായും അവതരിപ്പിക്കാൻ ശ്രമിക്കണം.\n3. നേരത്തെ റെക്കോർഡ് ചെയ്ത് സബ്‌മിറ്റ് ചെയ്യുന്ന രീതിയിലാണ് ക്രമീകരിക്കേണ്ടത്.\n4. വീഡിയോക്ക് മതിയായ ക്വാളിറ്റി ഉണ്ടാകണം.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ബുക്ക് ടെയ്‌ൽ"},{"id":"d0af059a-2700-432c-a9df-040afed1394f","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Moulid Recitation","guidelines":"1. സുബ്‌ഹാന മൗലീദ്, മുഹ്‌യിദ്ദീൻ മൗലിദ്, ബദ്‌ർ മൗലിദ് (വളപ്പിൽ അബ്ദുൽ അസീസ് മുസ്‌ലിയാർ രചിച്ച ബദ്‌ർ മൗലിദ് ചെറുത്) എന്നിവയിൽ നിന്ന് വിധികർത്താക്കൾ നിശ്ചയിക്കുന്ന ഭാഗമാണ് ആലപിക്കേണ്ടത്.\n2. ബൈത്ത് മാത്രമാണ് മത്സരത്തിന് പരിഗണിക്കുക.\n3. അവതരണ രീതി, ശ്രുതിലയം, അംഗങ്ങൾ തമ്മിലുള്ള യോജിപ്പ്, താളം-ബൈത്ത്, അക്ഷര സ്ഫുടത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മൗലിദ് പാരായണം"},{"id":"d33150c9-6d5e-4f12-837e-e3f0e043f379","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Capture the Flag","guidelines":"1. ടീം വർക്ക്, മെന്റൽ എബിലിറ്റി, റീസണിംഗ് തുടങ്ങിയവ ആവശ്യമുള്ള ഒരു ഗ്രൂപ്പ് മത്സരമാണ് ഇത്.\n2. ജില്ലാ തലം മുതലാണ് മത്സരം.\n3. ഒരു മണിക്കൂർ സമയം കൊണ്ട് 4 പേരടങ്ങുന്ന ടീം സൂചനകളിലൂടെ അവസാന ഉത്തരത്തിൽ എത്തുകയാണ് മത്സരം.\n4. ഇൻഡോർ ആയാണ് മത്സരം നടക്കുക. മൊബൈൽ ഫോൺ ഉപയോഗിക്കാം.\n5. അവസാന ഉത്തരം ഒരു പദാവലിയോ സംഖ്യയോ നാമങ്ങളോ മറ്റോ ആവാം.\n6. സാമൂഹികമോ മതപരമോ ആയ തെറ്റായ വിവരങ്ങൾ ഉണ്ടാവരുത്.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"കാപ്‌ചർ ദ ഫ്‌ളാഗ്"},{"id":"e27e0058-32d4-477a-a1b4-4d4affe88052","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Madh Song Writing","guidelines":"1. പ്രവാചകന്മാർ, സ്വഹാബികൾ, മറ്റ് പുണ്യാത്മാക്കൾ, അവരുടെ ജീവിത വഴികൾ എന്നിവയിൽ നിന്ന് മത്സരഹാളിൽ നിർദ്ദേശിക്കുന്ന വിഷയത്തിലാണ് മദ്‌ഹ്‌ഗാന രചന നടക്കേണ്ടത്.\n2. രചന 12 മുതൽ 16 വരെ വരിയിൽ ഉൾകൊള്ളിക്കുക. 16 വരിയിൽ കവിയരുത്.\n3. കൂൾ ഓഫ് ടൈം: 10 മിനിട്ട്.\n4. വിഷയം, പ്രാസം, താളം, സാഹിത്യം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"40m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"മദ്‌ഹ്‌ഗാന രചന"},{"id":"e34f4154-0ae5-43ea-919c-8772d589617f","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Mala Pattu","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"മാലപ്പാട്ട്"},{"id":"e422b056-cd25-4dae-b139-72c1eaddef27","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Madh Song","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"മദ്ഹ് ഗാനം"},{"id":"e61650ac-226d-4933-84e7-13f9f6f1f17a","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Journal Art","guidelines":"1. വിദ്യാർഥിയുടെ വിവിധ തരം സൃഷ്ടികൾ ക്രോഡീകരിച്ച് പുസ്തക രൂപത്തിൽ തയ്യാറാക്കുന്നതാണ് ജേർണൽ ആർട്ട്.\n2. ആശയം, സൃഷ്ടികളിലെ സർഗ്ഗാത്മകത, രചന, രൂപകൽപ്പന തുടങ്ങിയവ മാനദണ്ഡമാക്കിയാണ് വിധിനിർണ്ണയം നടക്കേണ്ടത്.\n3. ആകെ ഇരുപതിലധികം പേപ്പറുകളിലേക്ക് പോകരുത്.\n4. ഓരോ പേജും കാഴ്ചകളുടെയും എഴുത്തുകളുടെയും കൂട്ടായ്മയിലൂടെ ഒരു അർഥവത്തായ സൃഷ്ടിയുണ്ടാക്കുക എന്നതാണ് ചുരുക്കം.\n5. വര, പെയ്ന്റിംഗ്, കൊളാജ് എന്നിവയും വ്യക്തിപരമായ ആലോചനകൾ, ഉദ്ധരണികൾ, കവിതകൾ, എന്നിവകളും ഉൾപ്പെടുത്താം.\n6. സൃഷ്ടികളും രൂപകൽപ്പനയും വിദ്യാർഥിയുടേത് മാത്രമാകണം (മനുഷ്യരോ മറ്റ് ജീവജാലങ്ങളോ ഉണ്ടാവരുത്).","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ജേർണൽ ആർട്ട്"},{"id":"e6b38c1b-1a82-4d56-80ca-54341fd100e1","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Top Comment","guidelines":"1. സാഹിത്യോത്സവിനെ കാമ്പസിലെ മുഴുവൻ വിദ്യാർഥികളിലേക്കും എത്തിക്കുന്നതിന് മുൻഗണന നൽകിയാണ് യൂണിറ്റ് തലത്തിൽ ഈ മത്സരം നടക്കേണ്ടത്.\n2. കാമ്പസ് പരിസരത്ത് സ്ഥാപിക്കപ്പെടുന്ന ചിത്രത്തിന് കമന്റ് നൽകുകയാണ് മത്സരം.\n3. സോഷ്യൽ മീഡിയയിൽ കമന്റ് ഇടുന്ന രീതിയിൽ കവിത ശകലമോ ഗദ്യമോ ആവാം.\n4. കമന്റിന്റെ ആശയത്തിനും സർഗ്ഗാത്മകതക്കും പ്രാധാന്യം നൽകുക.\n5. ചിത്രം ആകർഷകമായ നിലയിൽ ചാർട്ട് പേപ്പറിലോ ഫ്‌ളക്‌സിലോ കാമ്പസ് യൂണിറ്റ് സാഹിത്യോത്സവ് പരസ്യപ്പെടുത്തും വിധം തയ്യാർ ചെയ്ത് സ്ഥാപിക്കണം.\n6. ഡിവിഷൻ ഘടകം മുതൽ ഈ മത്സരം മറ്റ് ഓഫ്‌സ്റ്റേജ് മത്സരങ്ങൾ പോലെ തന്നെ നടക്കേണ്ടതാണ്.\n7. 30 മിനിട്ട് സമയം കൊണ്ട് നൽകപ്പെടുന്ന ചിത്രത്തിന് മേൽ വിശദീകരിച്ച പ്രകാരമുള്ള കമന്റ് എഴുതുകയാണ് വേണ്ടത്.\n8. ആശയ വ്യക്തത, ഭാവന എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ടോപ്പ് കമന്റ്"},{"id":"e8cd832a-652f-4710-abb3-5b43a2a558dd","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Pencil Drawing","guidelines":"1. നൽകപ്പെടുന്ന ആശയത്തെ അധികരിച്ചാണ് വരക്കേണ്ടത്.\n2. പെൻസിലും മറ്റ് ഉപകരണങ്ങളും മത്സരാർഥികൾ കരുതണം.\n3. പ്രോഗ്രാം കമ്മിറ്റി നൽകുന്ന A4 പേപ്പറിലാണ് ചിത്രം വരക്കേണ്ടത്.\n4. ലോവർ പ്രൈമറി, അപ്പർ പ്രൈമറി ഒഴികെ വിഭാഗങ്ങളിൽ ചിത്രരചന പെൻസിൽ, ചിത്രരചന ജലച്ചായം മത്സരങ്ങളിൽ വരക്കുന്ന ചിത്രങ്ങളുടെ ആശയം എഴുതിച്ചേർക്കേണ്ടതാണ്.\n5. ആവശ്യമായ A4 ഷീറ്റ് ഉപയോഗിക്കാവുന്നതാണ്.\n6. ആശയ വ്യക്തത, സംവിധാനം, പ്രയോഗ മികവ്, രേഖകളുടെയും ഇരുൾ വെളിച്ചങ്ങളുടെയും സമ്മിശ്രണം, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"പെൻസിൽ ഡ്രോയിംഗ്"},{"id":"e933be76-6e9e-4c3a-a3ea-b16dc74b617c","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Daf Mutt","guidelines":null,"is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ദഫ് മുട്ട്"},{"id":"e9456562-dd30-40cd-8191-0bdc290ce0e3","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Qaseeda Recitation","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"ഖസീദ പാരായണം"},{"id":"e9d211dc-c86c-4bd5-89bf-93c386a1a4ed","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Digital Painting","guidelines":"1. നൽകുന്ന വിഷയത്തിൽ ഡിജിറ്റൽ ടൂളുകൾ ഉപയോഗിച്ച് മൊബൈൽ/ടാബ്‌ലെറ്റിലാണ് വരക്കേണ്ടത്.\n2. ഫൈനൽ പ്രൊഡക്ടിന്റെ ആശയം ഇമേജിൽ തന്നെ അടിക്കുറിപ്പായി ചേർത്ത് വിധിനിർണ്ണയത്തിനായി JPG ഫോർമാറ്റിൽ നൽകേണ്ടതാണ്.\n3. ആശയ വ്യക്തത, സംവിധാനം, ചായത്തിന്റെ മികവ്, ശൈലി, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഡിജിറ്റൽ പെയ്ന്റിംഗ്"},{"id":"f1692f7d-0e84-42ca-bcbb-fa3609d4b68e","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Embroidery","guidelines":"1. ഒരു കുഷ്യൻ കവറിനോ തലയണ കവറിനോ പറ്റിയ വലിപ്പത്തിലുള്ള തുണിയിലാണ് തുന്നൽ നടത്തേണ്ടത്.\n2. നൂൽ ഒറ്റ ലെയർ ആയോ മൾട്ടി ലെയർ ആയോ ഉപയോഗിക്കാം.\n3. തയ്യാറാക്കുന്ന ചിത്രത്തിന്റെ സ്വഭാവമനുസരിച്ച് അനുയോജ്യമായ തുന്നലുകൾ ഉപയോഗിക്കേണ്ടതാണ്.\n4. മഷിനോ കോട്ടൺ അല്ലാത്ത ക്ലോത്തുകളോ ഉപയോഗിക്കാൻ പാടില്ല.\n5. വിവിധയിനം തുന്നലുകൾ, നിറങ്ങളുടെ യോജിപ്പ്, നിറങ്ങളുടെ മികവ്, പൂർണത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ചിത്ര തുന്നൽ"},{"id":"f28d2c86-7467-4a48-8b11-d1f5050794b5","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Family Magazine","guidelines":"1. നിർദ്ദേശിക്കപ്പെട്ട വിഷയത്തെ അടിസ്ഥാനമാക്കി ഒറ്റ കുടുംബത്തിലെ അംഗങ്ങൾ തയ്യാറാക്കുന്ന കലാസൃഷ്ടിയാണ് ഫാമിലി മാഗസിൻ.\n2. ആശയം, സാഹിത്യം, സംവിധാനം, സർഗ്ഗാത്മകത എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"ഫാമിലി മാഗസിൻ"},{"id":"f4254c12-cb6c-4c41-9419-25e6f55076cb","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Arabana","guidelines":"1. അറബന മുട്ടിൽ ഊർജ്ജസ്വലനായ അഭ്യാസിയുടെ രൂപഭാവങ്ങൾ ദൃശ്യമാവണം.\n2. അറബനയുടെ ശബ്ദം ഉയർത്തുന്നതിനനുസരിച്ച് ബൈത്തിന്റെ ഗതിവേഗതയും കൂടേണ്ടതാണ്.\n3. അംഗോപാംഗങ്ങളിൽ തട്ടിയും മുട്ടിയും വിവിധ താളങ്ങളിലൂടെ അവതരിപ്പിക്കണം.\n4. പിന്നണി പാടില്ല. അറബി ബൈത്തുകളും രിഫാഇ ബൈത്തുകളും അനുവദനീയമാണ്.\n5. ആത്മീയ ഭാവം പ്രകടിപ്പിക്കണം.\n6. വേഷം: വെള്ള തുണി, വെള്ള ഷർട്ട്, വെള്ള തലപ്പാവ്.\n7. അറബനയിൽ ചിലങ്ക അനുവദനീയമാണ്. അറബനക്ക് 12 ഇഞ്ച് വ്യാസമുണ്ടായിരിക്കണം.\n8. ബൈത്ത്, ശ്രുതിലയം, ഭാവം, മെയ്‌താളവും വാദ്യ വാദനവും, അവതരണം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"10m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"അറബന"},{"id":"f7dd042a-a64f-445a-a7df-a44da3be6a8d","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Literary Discussion","guidelines":null,"is_default":true,"time_limit":null,"updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"സാഹിത്യ ചർച്ച"},{"id":"f80f38ee-34bf-461e-8b28-8766c61c1043","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Social Text","guidelines":"1. നൽകപ്പെടുന്ന വിഷയ ആശയത്തിലുള്ള ഒരു പാരഗ്രാഫ് പ്രതികരണ കുറിപ്പ് ഒരു പുറത്തിൽ കവിയാതെ തയ്യാറാക്കുക.\n2. നിലപാട്, ആശയ വ്യക്തത, ഭാഷ എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"30m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"സോഷ്യൽ ടെക്‌സ്റ്റ്"},{"id":"fbacf9f3-2a10-4ea1-abf9-56d9907f7d32","tenant_id":null,"created_at":"2026-10-11T05:51:09.649612+00:00","entry_mode":"criteria","event_name":"Story Telling","guidelines":null,"is_default":true,"time_limit":"5m","updated_at":"2026-10-11T05:51:09.649612+00:00","total_marks":100,"event_name_ml":"കഥ പറച്ചിൽ"},{"id":"ff245de7-9262-4040-9026-db2d43371c9e","tenant_id":null,"created_at":"2026-10-11T05:52:05.316915+00:00","entry_mode":"criteria","event_name":"Reel Making","guidelines":"1. നിർദ്ദേശിക്കപ്പെടുന്ന വിഷയത്തെ കുറിച്ച് സോഷ്യൽ മീഡിയയിൽ പോസ്റ്റ് ചെയ്യാൻ പറ്റുന്ന രൂപത്തിലുള്ള റീൽ തയ്യാറാക്കുക.\n2. ഇസ്‌ലാമിക വിരുദ്ധമായ എലമെന്റുകൾ വീഡിയോയിൽ ഉപയോഗിക്കാൻ പാടുള്ളതല്ല.\n3. ഹയർ സെക്കൻഡറി വിഭാഗത്തിൽ നേരത്തെ നൽകപ്പെടുന്ന വിഷയത്തിൽ തയ്യാറാക്കി സബ്‌മിറ്റ് ചെയ്യുകയാണ് വേണ്ടത്.\n4. ജൂനിയർ വിഭാഗത്തിൽ സാഹിത്യോത്സവ് നഗരിയിൽ നിന്നും നൽകപ്പെടുന്ന തീമിൽ ലൈവായി വീഡിയോ പകർത്തി 1 മിനിട്ട് ദൈർഘ്യമുള്ള റീൽ ആക്കുകയാണ് വേണ്ടത്. 30 മിനിട്ട് ലൈവ് റെക്കോർഡിങ്ങിനും 30 മിനിട്ട് എഡിറ്റിംഗിനും സമയം ലഭിക്കും.\n5. മൊബൈൽ ഫോൺ ഉപയോഗിച്ചാണ് വീഡിയോ റെക്കോർഡ് ചെയ്യേണ്ടത്.\n6. നിശ്ചയിക്കപ്പെടുന്ന സമയത്തിന് മുമ്പായി വീഡിയോ യൂട്യൂബിൽ പ്രൈവേറ്റായി അപ്‌ലോഡ് ചെയ്ത് ലിങ്ക് മെയിൽ ചെയ്യണം.\n7. ആശയ വ്യക്തത, അവതരണ മികവ്, ഇന്നൊവേഷൻ, ശബ്ദ ദൃശ്യ സമന്വയം, ശബ്ദ ദൃശ്യ നിലവാരം എന്നിവ വിലയിരുത്തുക.","is_default":true,"time_limit":"60m","updated_at":"2026-10-11T05:52:05.316915+00:00","total_marks":100,"event_name_ml":"റീൽ മേക്കിംഗ്"}]$festos_scoring_rules_json$);
