CREATE TEMP TABLE _festos_seed_application_feature_flags ON COMMIT DROP AS
  SELECT * FROM jsonb_populate_recordset(NULL::stage_portal_private.application_feature_flags, $festos_application_feature_flags_json$[{"flag":"main_admin_dashboard","enabled":true,"updated_at":"2026-10-29T03:33:40.703953+00:00"}]$festos_application_feature_flags_json$);

DO $guard$
BEGIN
  IF EXISTS (SELECT 1 FROM _festos_seed_categories WHERE tenant_id IS NOT NULL) THEN RAISE EXCEPTION 'Global category seed contains tenant-owned rows'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_items WHERE tenant_id IS NOT NULL OR festival_id IS NOT NULL) THEN RAISE EXCEPTION 'Global item seed contains tenant/festival-owned rows'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_scoring_rules WHERE tenant_id IS NOT NULL) THEN RAISE EXCEPTION 'Global scoring rule seed contains tenant-owned rows'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_categories s JOIN public.categories t USING(id)) THEN RAISE EXCEPTION 'Target categories collision'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_items s JOIN public.items t USING(id)) THEN RAISE EXCEPTION 'Target items collision'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_scoring_rules s JOIN public.scoring_rules t USING(id)) THEN RAISE EXCEPTION 'Target scoring_rules collision'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_scoring_criteria s JOIN public.scoring_criteria t USING(id)) THEN RAISE EXCEPTION 'Target scoring_criteria collision'; END IF;
  IF EXISTS (SELECT 1 FROM _festos_seed_application_feature_flags s JOIN stage_portal_private.application_feature_flags t USING(flag)) THEN RAISE EXCEPTION 'Target application_feature_flags collision'; END IF;
  IF (SELECT count(*) FROM _festos_seed_categories) <> 11 THEN RAISE EXCEPTION 'Unexpected categories seed count'; END IF;
  IF (SELECT count(*) FROM _festos_seed_items) <> 170 THEN RAISE EXCEPTION 'Unexpected items seed count'; END IF;
  IF (SELECT count(*) FROM _festos_seed_scoring_rules) <> 83 THEN RAISE EXCEPTION 'Unexpected scoring_rules seed count'; END IF;
  IF (SELECT count(*) FROM _festos_seed_scoring_criteria) <> 384 THEN RAISE EXCEPTION 'Unexpected scoring_criteria seed count'; END IF;
  IF (SELECT count(*) FROM _festos_seed_application_feature_flags) <> 1 THEN RAISE EXCEPTION 'Unexpected application_feature_flags seed count'; END IF;
END;
$guard$;

INSERT INTO public.categories (id, code, gender, age_max, age_min, name_ml, class_max, class_min, is_active, tenant_id)
SELECT id, code, gender, age_max, age_min, name_ml, class_max, class_min, is_active, tenant_id FROM _festos_seed_categories;

INSERT INTO public.items (id, gender, source, is_active, item_code, item_type, tenant_id, paper_size, updated_at, daf_allowed, festival_id, custom_rules, item_name_en, item_name_ml, book_by_level, drawing_topic, speech_topics, category_codes, ishal_required, duration_minutes, calligraphy_style, group_max_members, group_min_members, level_availability, participation_type, members_locked_after, originality_required, white_dress_required, regional_dialect_blocked, max_participants_per_team, organizer_provides_material)
SELECT id, gender, source, is_active, item_code, item_type, tenant_id, paper_size, updated_at, daf_allowed, festival_id, custom_rules, item_name_en, item_name_ml, book_by_level, drawing_topic, speech_topics, category_codes, ishal_required, duration_minutes, calligraphy_style, group_max_members, group_min_members, level_availability, participation_type, members_locked_after, originality_required, white_dress_required, regional_dialect_blocked, max_participants_per_team, organizer_provides_material FROM _festos_seed_items;

INSERT INTO public.scoring_rules (id, tenant_id, created_at, entry_mode, event_name, guidelines, is_default, time_limit, updated_at, total_marks, event_name_ml)
SELECT id, tenant_id, created_at, entry_mode, event_name, guidelines, is_default, time_limit, updated_at, total_marks, event_name_ml FROM _festos_seed_scoring_rules;

INSERT INTO public.scoring_criteria (id, name, marks, rule_id, created_at, sort_order)
SELECT id, name, marks, rule_id, created_at, sort_order FROM _festos_seed_scoring_criteria;

INSERT INTO stage_portal_private.application_feature_flags (flag, enabled, updated_at)
SELECT flag, enabled, updated_at FROM _festos_seed_application_feature_flags;


